// /frontend-react/src/components/ProfilePage.js

import React, { useState } from 'react';
import HeaderBar from './HeaderBar';

// --- Local Mock Profile Data (Primary Data is non-editable) ---
const mockProfileData = {
    name: "LIM CHIN WEI",
    icNumber: "851020-07-5XXX",
    dateOfBirth: "20 / OCTOBER / 1985",
    address: "NO. 12, JALAN SAGA, KUALA LUMPUR",
    // Initial value for the editable field
    initialEmergencyContact: "CHIN YEE (012-3456789)", 
};

function ProfilePage({ isEasyMode, goToPage, onMenuClick }) {
    const profile = mockProfileData;
    
    // State to manage the editable emergency contact field
    const [emergencyContact, setEmergencyContact] = useState(profile.initialEmergencyContact);
    const [isEditing, setIsEditing] = useState(false);

    // Function to handle saving the updated contact
    const handleSaveContact = () => {
        // In a real app: Send the updated 'emergencyContact' value to the Python backend.
        console.log("Profile Updated! New Emergency Contact:", emergencyContact);
        setIsEditing(false);
        alert(`Emergency contact saved as: ${emergencyContact}`);
    };

    // --- NON-EDITABLE InfoCard Component ---
    const InfoCard = ({ title, value, isEditable = false }) => (
        <div style={{
            padding: '25px', 
            margin: '8px 0', 
            width: '100%',
            backgroundColor: '#fff',
            borderBottom: '1px solid #e0e0e0',
            textAlign: 'left',
            position: 'relative', // Context for edit button
        }}>
            {/* Title (Label) */}
            <p style={{ 
                fontSize: isEasyMode ? '22px' : '15px', 
                fontWeight: '600', 
                margin: '0 0 5px 0', 
                color: isEditable ? 'darkorange' : '#6c757d'
            }}>
                {title.toUpperCase()}
            </p>
            
            {/* Value (Read-only display for non-editable fields) */}
            {!isEditable && (
                <p style={{ 
                    fontSize: isEasyMode ? '34px' : '22px', 
                    fontWeight: 'bold',
                    margin: 0, 
                    color: '#333' 
                }}>
                    {value}
                </p>
            )}
            
            {/* Editable Input Field */}
            {isEditable && (
                <input
                    type="text"
                    value={emergencyContact}
                    onChange={(e) => setEmergencyContact(e.target.value)}
                    disabled={!isEditing}
                    style={{
                        width: '100%',
                        padding: '10px 0',
                        fontSize: isEasyMode ? '34px' : '22px',
                        border: 'none',
                        borderBottom: isEditing ? '2px solid darkorange' : 'none',
                        backgroundColor: 'transparent',
                        fontWeight: 'bold',
                        color: '#333'
                    }}
                />
            )}

            {/* Edit Button for the Emergency Contact Field */}
            {isEditable && !isEditing && (
                <button
                    onClick={() => setIsEditing(true)}
                    style={{
                        position: 'absolute',
                        top: '15px',
                        right: '15px',
                        padding: '5px 10px',
                        fontSize: isEasyMode ? '20px' : '12px',
                        backgroundColor: '#1A73E8',
                        color: 'white',
                        border: 'none',
                        borderRadius: '5px',
                    }}
                >
                    EDIT ✍️
                </button>
            )}
        </div>
    );
    // --- END InfoCard ---

    return (
        <div style={{ padding: '0 0 20px 0', textAlign: 'center' }}>
            <HeaderBar
                title="Profile"
                onBackClick={() => goToPage('dashboard')}
                onMenuClick={onMenuClick}
                isEasyMode={isEasyMode}
            />

            <h2 style={{ fontSize: isEasyMode ? '40px' : '30px', margin: '30px 0 20px 0', color: '#333' }}>
                Personal Details
            </h2>

            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', width: '100%', padding: '0 10px' }}>
                {/* Non-Editable Fields (Extracted from IC/Backend) */}
                <InfoCard title="Name" value={profile.name} isEasyMode={isEasyMode}/>
                <InfoCard title="IC Number" value={profile.icNumber} isEasyMode={isEasyMode}/>
                <InfoCard title="Date of Birth" value={profile.dateOfBirth} isEasyMode={isEasyMode}/>
                <InfoCard title="Address" value={profile.address} isEasyMode={isEasyMode}/>

                {/* Editable Field */}
                <InfoCard 
                    title="Emergency Contact" 
                    value={emergencyContact} 
                    isEditable={true} 
                    isEasyMode={isEasyMode}
                />

                {/* Save Button (Only Visible when Editing) */}
                {isEditing && (
                    <button
                        onClick={handleSaveContact}
                        style={{
                            padding: '18px 35px', 
                            fontSize: isEasyMode ? '30px' : '20px', 
                            backgroundColor: 'darkorange',
                            color: 'white',
                            border: 'none',
                            borderRadius: '10px',
                            marginTop: '30px',
                            fontWeight: 'bold',
                        }}
                    >
                        SAVE CHANGES ✅
                    </button>
                )}
            </div>
        </div>
    );
}

export default ProfilePage;
